import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/en/provedores-detalhe.png",s="/pro-agent-hub-installer/capturas/en/modelos-detalhe.png",u=JSON.parse('{"title":"Providers and models","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/provedores-modelos.md","filePath":"en/interface/provedores-modelos.md","lastUpdated":1787856241000}'),i={name:"en/interface/provedores-modelos.md"};function d(l,e,p,c,h,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="providers-and-models" tabindex="-1">Providers and models <a class="header-anchor" href="#providers-and-models" aria-label="Permalink to &quot;Providers and models&quot;">​</a></h1><p>This is where everything starts. An agent without a model will not save, and a model without a provider does not exist.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p><img src="'+n+'" alt="provedores-detalhe"></p><p>A <strong>provider</strong> is where the intelligence comes from: OpenAI, Anthropic, Google or an Ollama running on your own machine. The record holds the type, the address and the API key.</p><p><strong>The key travels in the export file</strong>, encrypted — but with a default key that lives in the source, which protects against casual reading and not against someone determined. Worth knowing before you send an export to someone. See <a href="/pro-agent-hub-installer/en/interface/administracao#import-and-export">Import and export</a>.</p><p><strong>Ollama asks for no key.</strong> It runs alongside the installation and the default address comes pre-filled. It is the way to depend on no paid service and send no data outside.</p><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><p><img src="'+s+'" alt="modelos-detalhe"></p><p>A <strong>model</strong> is one specific model of a provider — <code>gpt-4o</code> from OpenAI, <code>nomic-embed-text</code> from Ollama. The same name can exist under different providers, and the platform treats them as separate records.</p><p>Two switches decide where it can be used:</p><ul><li><strong>Use in chat</strong> — it can be the brain of an agent, team or planner.</li><li><strong>Use in embedding</strong> — it can vectorise a knowledge base.</li></ul><p>An embedding model has a <strong>dimension</strong>, and it has to match the vectors already stored. Changing the embedding model of a knowledge base that has already been vectorised requires a full reload — the collection is recreated with the new dimension.</p><h3 id="price-and-limits" tabindex="-1">Price and limits <a class="header-anchor" href="#price-and-limits" aria-label="Permalink to &quot;Price and limits {#price-and-limits}&quot;">​</a></h3><p>The record accepts a price per million tokens (input and output) and daily and monthly usage caps, by tokens or by cost.</p><p><strong>The cap has two stages</strong>, and the difference matters before you configure it:</p><ul><li>Crossing the <strong>alert percentage</strong> e-mails the master users and carries on working.</li><li>Crossing the <strong>limit</strong>, with <em>block</em> on, makes runs of that model be refused.</li></ul><p>With no price on record there is no cost to track — only a token count. Tracking lives in <a href="/pro-agent-hub-installer/en/interface/administracao#token-usage">Token usage</a>.</p>',18)])])}const f=o(i,[["render",d]]);export{u as __pageData,f as default};
